import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    static int[] solve(int[] num, int k) {
        // Write your logic here

        return new int[0];
    }

    // ---------- input / output is handled below, no need to change it ----------

    public static void main(String[] args) throws IOException {
        int[] num = readIntArray();
        int k = readInt();
        int[] ans = solve(num, k);
        System.out.println(Arrays.stream(ans).mapToObj(String::valueOf).collect(Collectors.joining(" ")));
    }

    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

    static String readLine() throws IOException {
        String s = br.readLine();
        return s == null ? "" : s;
    }

    static int readInt() throws IOException {
        return Integer.parseInt(readLine().trim());
    }

    static int[] readInts() throws IOException {
        String s = readLine().trim();
        if (s.isEmpty()) return new int[0];
        String[] parts = s.split("\\s+");
        int[] a = new int[parts.length];
        for (int i = 0; i < parts.length; i++) a[i] = Integer.parseInt(parts[i]);
        return a;
    }

    static int[] readIntArray() throws IOException {
        int n = readInt();
        int[] a = readInts();
        return a.length == n ? a : Arrays.copyOf(a, n);
    }
}

